def next_smallest_palindrome(n):
    def is_palindrome(num):
        """Check if a number is a palindrome."""
        s = str(num)
        return s == s[::-1]

    def create_palindrome(left_half, odd_length):
        """Create a palindrome by mirroring the left half."""
        if odd_length:
            return int(left_half + left_half[-2::-1])
        else:
            return int(left_half + left_half[::-1])

    s = str(n)
    length = len(s)
    odd_length = length % 2 != 0

    # Split the number into left half and middle digit if odd-length
    if odd_length:
        left_half = s[:length // 2 + 1]
    else:
        left_half = s[:length // 2]

    # Create a candidate palindrome by mirroring the left half
    candidate = create_palindrome(left_half, odd_length)

    # If candidate is greater than n, return it
    if candidate > n:
        return candidate

    # Otherwise, increment the left half (including middle digit if odd-length)
    incremented_left = str(int(left_half) + 1)

    # Handle cases where incrementing the left half increases the digit count
    if len(incremented_left) > len(left_half):
        # For cases like 999 -> 1001, simply return the next power of 10 + 1
        return int("1" + "0" * (length - 1) + "1")

    # Create the next palindrome using the incremented left half
    return create_palindrome(incremented_left, odd_length)

# Example Usage and Test Cases
assert next_smallest_palindrome(99) == 101
assert next_smallest_palindrome(123) == 131
assert next_smallest_palindrome(9) == 11
assert next_smallest_palindrome(808) == 818
assert next_smallest_palindrome(999) == 1001
