def maximize_elements(tuple1, tuple2):
    """
    Maximizes elements of two tuples element-wise.

    Parameters:
    tuple1 (tuple): The first tuple containing sub-tuples of numeric values.
    tuple2 (tuple): The second tuple containing sub-tuples of numeric values.

    Returns:
    tuple: A new tuple containing sub-tuples with element-wise maximum values.
    """
    # Validate inputs
    if not isinstance(tuple1, tuple) or not isinstance(tuple2, tuple):
        raise ValueError("Both inputs must be tuples.")
    if len(tuple1) != len(tuple2):
        raise ValueError("Input tuples must have the same length.")

    # Validate structure of sub-tuples
    for sub1, sub2 in zip(tuple1, tuple2):
        if not isinstance(sub1, tuple) or not isinstance(sub2, tuple):
            raise ValueError("All elements of input tuples must be tuples.")
        if len(sub1) != len(sub2):
            raise ValueError("Corresponding sub-tuples must have the same length.")

    # Compute the maximized tuple
    return tuple(
        tuple(max(a, b) for a, b in zip(sub1, sub2))
        for sub1, sub2 in zip(tuple1, tuple2)
    )
