def average_tuple(data):
    if not isinstance(data, tuple):
        raise TypeError("Input should be a tuple of tuples.")

    averages = []
    for tup in data:
        if not isinstance(tup, tuple):
            raise TypeError("Each element in the input should be a tuple.")

        if len(tup) == 0:
            averages.append(0)  # Handle empty tuples by appending 0
            continue

        if not all(isinstance(x, (int, float)) for x in tup):
            raise ValueError("All elements in the tuples should be numeric.")

        avg = sum(tup) / len(tup)
        averages.append(avg)

    return averages

