def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merges three dictionaries into a single dictionary, ensuring that keys 
    from dict3 take precedence over dict2, which in turn take precedence over dict1.
    """
    # Merge dictionaries with precedence: dict1 < dict2 < dict3
    merged_dict = {**dict1, **dict2, **dict3}
    return merged_dict

